/**
 * DesignDocumentStorage - File storage for Design workflow documents
 *
 * Handles persistence of markdown documents generated by DocumentGenerator:
 * - Style guide: .personaut/design/{project-name}/style-guide.md
 * - Steering document: .personaut/design/{project-name}/steering-document.md
 * - Task list: .personaut/design/{project-name}/task-list.md
 * - Page requirements: .personaut/design/{project-name}/pages/{page-id}.md
 * - User flows: .personaut/design/{project-name}/flows/{flow-id}.md
 *
 * Uses existing FileStorageService patterns for atomic writes and directory management.
 *
 * **Part of Build-to-Design Transformation**
 * Validates: Requirements 8B.8, 10.3, 11.3, 24.8, 24.9
 */

import * as fs from 'fs';
import * as path from 'path';

// ============================================================================
// TYPES
// ============================================================================

/**
 * Document types for Design workflow
 */
export type DesignDocumentType =
    | 'style-guide'
    | 'steering-document'
    | 'task-list'
    | 'page-requirements'
    | 'user-flow';

/**
 * Document metadata stored alongside content
 */
export interface DocumentMetadata {
    documentType: DesignDocumentType;
    projectName: string;
    identifier?: string; // For page-requirements and user-flow
    generatedAt: string;
    version: string;
}

/**
 * Result of a write operation
 */
export interface WriteResult {
    success: boolean;
    filePath: string;
    error?: string;
}

/**
 * Result of a read operation
 */
export interface ReadResult {
    success: boolean;
    content?: string;
    metadata?: DocumentMetadata;
    error?: string;
}

/**
 * Export result for all documents
 */
export interface ExportResult {
    success: boolean;
    exportedFiles: string[];
    errors: string[];
}

/**
 * Storage configuration
 */
export interface StorageConfig {
    /** Base directory for .personaut files (workspace root) */
    baseDir: string;
    /** Project name (used in path) */
    projectName: string;
}

// ============================================================================
// CONSTANTS
// ============================================================================

/**
 * Base directory within .personaut for design documents
 */
export const DESIGN_DIR = 'design';

/**
 * Subdirectory for page requirement documents
 */
export const PAGES_SUBDIR = 'pages';

/**
 * Subdirectory for user flow documents
 */
export const FLOWS_SUBDIR = 'flows';

// ============================================================================
// DESIGN DOCUMENT STORAGE
// ============================================================================

/**
 * DesignDocumentStorage - Manages persistence of Design workflow documents
 */
export class DesignDocumentStorage {
    private readonly baseDir: string;
    private readonly projectName: string;
    private readonly projectDir: string;

    constructor(config: StorageConfig) {
        this.baseDir = config.baseDir;
        this.projectName = this.toKebabCase(config.projectName);
        this.projectDir = path.join(
            this.baseDir,
            '.personaut',
            DESIGN_DIR,
            this.projectName
        );
    }

    // ========================================================================
    // Path Generation
    // ========================================================================

    /**
     * Get the base design directory path
     * Returns: {baseDir}/.personaut/design/{project-name}/
     */
    public getDesignDir(): string {
        return this.projectDir;
    }

    /**
     * Get path for a document
     */
    public getDocumentPath(
        documentType: DesignDocumentType,
        identifier?: string
    ): string {
        switch (documentType) {
            case 'style-guide':
                return path.join(this.projectDir, 'style-guide.md');
            case 'steering-document':
                return path.join(this.projectDir, 'steering-document.md');
            case 'task-list':
                return path.join(this.projectDir, 'task-list.md');
            case 'page-requirements':
                if (!identifier) {
                    throw new Error('Page requirements require an identifier');
                }
                return path.join(
                    this.projectDir,
                    PAGES_SUBDIR,
                    `${this.toKebabCase(identifier)}.md`
                );
            case 'user-flow':
                if (!identifier) {
                    throw new Error('User flow requires an identifier');
                }
                return path.join(
                    this.projectDir,
                    FLOWS_SUBDIR,
                    `${this.toKebabCase(identifier)}.md`
                );
            default:
                throw new Error(`Unknown document type: ${documentType}`);
        }
    }

    /**
     * Get relative path for use with DocumentGenerator output paths
     */
    public getRelativePath(
        documentType: DesignDocumentType,
        identifier?: string
    ): string {
        const fullPath = this.getDocumentPath(documentType, identifier);
        return path.relative(this.baseDir, fullPath);
    }

    // ========================================================================
    // Write Operations
    // ========================================================================

    /**
     * Save a document to disk
     */
    public async saveDocument(
        documentType: DesignDocumentType,
        content: string,
        identifier?: string
    ): Promise<WriteResult> {
        const filePath = this.getDocumentPath(documentType, identifier);

        try {
            // Ensure directory exists
            const dir = path.dirname(filePath);
            await this.ensureDirectory(dir);

            // Write with atomic pattern (temp file + rename)
            await this.atomicWrite(filePath, content);

            console.log(`[DesignDocumentStorage] Saved ${documentType}: ${filePath}`);

            return {
                success: true,
                filePath,
            };
        } catch (error) {
            const errorMessage = error instanceof Error ? error.message : String(error);
            console.error(`[DesignDocumentStorage] Failed to save ${documentType}:`, errorMessage);

            return {
                success: false,
                filePath,
                error: errorMessage,
            };
        }
    }

    /**
     * Save the style guide document
     */
    public async saveStyleGuide(content: string): Promise<WriteResult> {
        return this.saveDocument('style-guide', content);
    }

    /**
     * Save the steering document
     */
    public async saveSteeringDocument(content: string): Promise<WriteResult> {
        return this.saveDocument('steering-document', content);
    }

    /**
     * Save the task list document
     */
    public async saveTaskList(content: string): Promise<WriteResult> {
        return this.saveDocument('task-list', content);
    }

    /**
     * Save a page requirements document
     */
    public async savePageRequirements(
        pageId: string,
        content: string
    ): Promise<WriteResult> {
        return this.saveDocument('page-requirements', content, pageId);
    }

    /**
     * Save a user flow document
     */
    public async saveUserFlow(
        flowId: string,
        content: string
    ): Promise<WriteResult> {
        return this.saveDocument('user-flow', content, flowId);
    }

    // ========================================================================
    // Read Operations
    // ========================================================================

    /**
     * Read a document from disk
     */
    public async readDocument(
        documentType: DesignDocumentType,
        identifier?: string
    ): Promise<ReadResult> {
        const filePath = this.getDocumentPath(documentType, identifier);

        try {
            const content = await fs.promises.readFile(filePath, 'utf-8');

            return {
                success: true,
                content,
                metadata: {
                    documentType,
                    projectName: this.projectName,
                    identifier,
                    generatedAt: new Date().toISOString(),
                    version: '1.0',
                },
            };
        } catch (error) {
            const errorMessage = error instanceof Error ? error.message : String(error);

            return {
                success: false,
                error: errorMessage,
            };
        }
    }

    /**
     * Check if a document exists
     */
    public async documentExists(
        documentType: DesignDocumentType,
        identifier?: string
    ): Promise<boolean> {
        const filePath = this.getDocumentPath(documentType, identifier);

        try {
            await fs.promises.access(filePath, fs.constants.F_OK);
            return true;
        } catch {
            return false;
        }
    }

    // ========================================================================
    // List Operations
    // ========================================================================

    /**
     * List all page requirement documents
     */
    public async listPageRequirements(): Promise<string[]> {
        const pagesDir = path.join(this.projectDir, PAGES_SUBDIR);
        return this.listMarkdownFiles(pagesDir);
    }

    /**
     * List all user flow documents
     */
    public async listUserFlows(): Promise<string[]> {
        const flowsDir = path.join(this.projectDir, FLOWS_SUBDIR);
        return this.listMarkdownFiles(flowsDir);
    }

    /**
     * List all documents in the design directory
     */
    public async listAllDocuments(): Promise<{
        styleGuide: boolean;
        steeringDocument: boolean;
        taskList: boolean;
        pageRequirements: string[];
        userFlows: string[];
    }> {
        const [styleGuide, steeringDocument, taskList, pageRequirements, userFlows] =
            await Promise.all([
                this.documentExists('style-guide'),
                this.documentExists('steering-document'),
                this.documentExists('task-list'),
                this.listPageRequirements(),
                this.listUserFlows(),
            ]);

        return {
            styleGuide,
            steeringDocument,
            taskList,
            pageRequirements,
            userFlows,
        };
    }

    // ========================================================================
    // Export Operations
    // ========================================================================

    /**
     * Export all documents (useful for batch save)
     */
    public async exportAll(documents: {
        styleGuide?: string;
        steeringDocument?: string;
        taskList?: string;
        pageRequirements?: Array<{ id: string; content: string }>;
        userFlows?: Array<{ id: string; content: string }>;
    }): Promise<ExportResult> {
        const exportedFiles: string[] = [];
        const errors: string[] = [];

        // Style guide
        if (documents.styleGuide) {
            const result = await this.saveStyleGuide(documents.styleGuide);
            if (result.success) {
                exportedFiles.push(result.filePath);
            } else {
                errors.push(`style-guide: ${result.error}`);
            }
        }

        // Steering document
        if (documents.steeringDocument) {
            const result = await this.saveSteeringDocument(documents.steeringDocument);
            if (result.success) {
                exportedFiles.push(result.filePath);
            } else {
                errors.push(`steering-document: ${result.error}`);
            }
        }

        // Task list
        if (documents.taskList) {
            const result = await this.saveTaskList(documents.taskList);
            if (result.success) {
                exportedFiles.push(result.filePath);
            } else {
                errors.push(`task-list: ${result.error}`);
            }
        }

        // Page requirements
        if (documents.pageRequirements) {
            for (const page of documents.pageRequirements) {
                const result = await this.savePageRequirements(page.id, page.content);
                if (result.success) {
                    exportedFiles.push(result.filePath);
                } else {
                    errors.push(`page-${page.id}: ${result.error}`);
                }
            }
        }

        // User flows
        if (documents.userFlows) {
            for (const flow of documents.userFlows) {
                const result = await this.saveUserFlow(flow.id, flow.content);
                if (result.success) {
                    exportedFiles.push(result.filePath);
                } else {
                    errors.push(`flow-${flow.id}: ${result.error}`);
                }
            }
        }

        return {
            success: errors.length === 0,
            exportedFiles,
            errors,
        };
    }

    // ========================================================================
    // Delete Operations
    // ========================================================================

    /**
     * Delete a document
     */
    public async deleteDocument(
        documentType: DesignDocumentType,
        identifier?: string
    ): Promise<boolean> {
        const filePath = this.getDocumentPath(documentType, identifier);

        try {
            await fs.promises.unlink(filePath);
            return true;
        } catch {
            return false;
        }
    }

    /**
     * Delete all design documents for the project
     */
    public async deleteAll(): Promise<boolean> {
        try {
            await fs.promises.rm(this.projectDir, { recursive: true, force: true });
            return true;
        } catch {
            return false;
        }
    }

    // ========================================================================
    // Private Helpers
    // ========================================================================

    /**
     * Convert string to kebab-case
     */
    private toKebabCase(str: string): string {
        return str
            .toLowerCase()
            .replace(/[^a-z0-9]+/g, '-')
            .replace(/^-+|-+$/g, '');
    }

    /**
     * Ensure a directory exists
     */
    private async ensureDirectory(dirPath: string): Promise<void> {
        try {
            await fs.promises.mkdir(dirPath, { recursive: true });
        } catch (error) {
            // Ignore EEXIST errors
            if ((error as NodeJS.ErrnoException).code !== 'EEXIST') {
                throw error;
            }
        }
    }

    /**
     * Atomic write using temp file + rename
     */
    private async atomicWrite(filePath: string, content: string): Promise<void> {
        const tempPath = `${filePath}.tmp.${Date.now()}`;

        try {
            await fs.promises.writeFile(tempPath, content, 'utf-8');
            await fs.promises.rename(tempPath, filePath);
        } catch (error) {
            // Clean up temp file on error
            try {
                await fs.promises.unlink(tempPath);
            } catch {
                // Ignore cleanup errors
            }
            throw error;
        }
    }

    /**
     * List markdown files in a directory
     */
    private async listMarkdownFiles(dirPath: string): Promise<string[]> {
        try {
            const entries = await fs.promises.readdir(dirPath, { withFileTypes: true });
            return entries
                .filter(entry => entry.isFile() && entry.name.endsWith('.md'))
                .map(entry => entry.name.replace('.md', ''));
        } catch {
            return [];
        }
    }
}

// ============================================================================
// FACTORY FUNCTION
// ============================================================================

/**
 * Create a DesignDocumentStorage instance
 */
export function createDesignDocumentStorage(
    baseDir: string,
    projectName: string
): DesignDocumentStorage {
    return new DesignDocumentStorage({
        baseDir,
        projectName,
    });
}
